<?php
/** Secciones neutrales de información del expediente. */
$sections = array_values(array_filter(
    (array) ($digitalRecord['information_sections'] ?? []),
    static function (array $section): bool {
        $content = $section['content'] ?? null;
        if (in_array(($section['id'] ?? ''), ['keywords', 'project-classification'], true)) return true;
        return is_array($content) ? $content !== [] : trim((string) $content) !== '';
    }
));
$recordMode = (string) ($digitalRecord['mode'] ?? 'view');
$recordForm = is_array($digitalRecord['form'] ?? null) ? $digitalRecord['form'] : [];
$formValues = is_array($recordForm['values'] ?? null) ? $recordForm['values'] : [];
$classificationTone = static function (string $label): string {
    $key = mb_strtolower($label, 'UTF-8');
    if (class_exists('Normalizer')) {
        $normalized = Normalizer::normalize($key, Normalizer::FORM_D);
        if (is_string($normalized)) $key = (string) preg_replace('/\p{Mn}+/u', '', $normalized);
    }
    return match ($key) {
        'tesis', 'perfil de tesis', 'guia documental' => 'blue',
        'titulacion', 'investigacion', 'proyecto pis' => 'purple',
        'metodologia', 'vinculacion', 'practicas preprofesionales' => 'green',
        default => 'yellow',
    };
};
